import sys
from collections import deque

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n, k = map(int, input[ptr:ptr+2])
        ptr +=2
        x = list(map(int, input[ptr:ptr+k]))
        ptr +=k
        adj = [[] for _ in range(n+1)]
        for __ in range(n-1):
            u, v = map(int, input[ptr:ptr+2])
            ptr +=2
            adj[u].append(v)
            adj[v].append(u)

        if k == 0:
            print(-1)
            continue

        leaves = []
        for i in range(1, n+1):
            if len(adj[i]) == 1:
                leaves.append(i)

        if 1 in leaves:
            leaves.remove(1)

        if not leaves:
            print(-1)
            continue

        parent = [0]*(n+1)
        q = deque([1])
        parent[1] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if parent[v] == 0 and v != parent[u]:
                    parent[v] = u
                    q.append(v)

        x_set = set(x)
        res = float('inf')
        for leaf in leaves:
            path = []
            u = leaf
            while u != 1:
                path.append(u)
                u = parent[u]
            path.append(1)
            path.reverse()
            mask = 0
            for node in path:
                if node in x_set:
                    mask |= (1 << (node-2))
            if mask == 0:
                continue
            cnt = bin(mask).count('1')
            if cnt < res:
                res = cnt
        if res == float('inf'):
            print(-1)
        else:
            print(res)

solve()
